INSERT INTO content_items (title, content, "order", chapter_id) VALUES
('The Cat and the Dog', '{"type": "article", "text": "A cat and a dog lived in a small house. They were good friends. Every day they played together in the garden.", "imageUrl": "https://example.com/cat-dog.jpg"}', 1, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('My Family', '{"type": "article", "text": "I have a big family. My mother is a teacher. My father works in a bank. I have one sister and one brother.", "imageUrl": "https://example.com/family.jpg"}', 2, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('Colors in Nature', '{"type": "article", "text": "Look at the sky. It is blue. The grass is green. The sun is yellow. Flowers can be red, pink, or white.", "imageUrl": "https://example.com/nature.jpg"}', 3, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('A Day at School', '{"type": "article", "text": "I go to school every morning. I carry my bag with books and a pencil. My teacher is very nice. We learn many things.", "imageUrl": "https://example.com/school.jpg"}', 4, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('The Weather Today', '{"type": "article", "text": "Today is sunny. The birds are singing. Children are playing outside. It is a beautiful day for a walk.", "imageUrl": "https://example.com/sunny-day.jpg"}', 5, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('Animals at the Zoo', '{"type": "article", "text": "At the zoo, we can see many animals. There are lions, elephants, and monkeys. The elephants are very big.", "imageUrl": "https://example.com/zoo.jpg"}', 6, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('My Favorite Food', '{"type": "article", "text": "I like to eat apples and bananas. Pizza is my favorite dinner. I drink milk every day. Vegetables are good for me.", "imageUrl": "https://example.com/food.jpg"}', 7, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('Playing in the Park', '{"type": "article", "text": "The park has many trees and flowers. Children run and play games. There is a big slide and swings to play on.", "imageUrl": "https://example.com/park.jpg"}', 8, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('My Bedroom', '{"type": "article", "text": "My bedroom is small but nice. I have a bed, a desk, and a chair. My toys are in a big box near the window.", "imageUrl": "https://example.com/bedroom.jpg"}', 9, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('The Little Bird', '{"type": "article", "text": "A little bird sits on a tree. It sings beautiful songs every morning. The bird has yellow feathers and a small beak.", "imageUrl": "https://example.com/bird.jpg"}', 10, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('Shopping with Mom', '{"type": "article", "text": "I go shopping with my mom. We buy bread, milk, and fruits. The store is big and has many things to choose from.", "imageUrl": "https://example.com/shopping.jpg"}', 11, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('My Pet Fish', '{"type": "article", "text": "I have a pet fish in a bowl. The fish is orange and swims all day. I feed my fish every morning before school.", "imageUrl": "https://example.com/fish.jpg"}', 12, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('The Magic Garden', '{"type": "article", "text": "In the garden, there are many flowers. Bees fly from flower to flower. Butterflies dance in the warm sunshine.", "imageUrl": "https://example.com/garden.jpg"}', 13, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('My Birthday Party', '{"type": "article", "text": "Today is my birthday! I have a big cake with candles. My friends come to my party. We play games and eat cake.", "imageUrl": "https://example.com/birthday.jpg"}', 14, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('The Busy Street', '{"type": "article", "text": "The street is very busy. Cars and buses move slowly. People walk on the sidewalk. There are many shops and buildings.", "imageUrl": "https://example.com/street.jpg"}', 15, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('Reading a Book', '{"type": "article", "text": "I love to read books. My favorite book has pictures of animals. Reading helps me learn new words and ideas.", "imageUrl": "https://example.com/reading.jpg"}', 16, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('The Beach Day', '{"type": "article", "text": "We go to the beach on weekends. The sand is warm and soft. The waves make a nice sound. I like to build sandcastles.", "imageUrl": "https://example.com/beach.jpg"}', 17, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('Cooking with Dad', '{"type": "article", "text": "My dad teaches me how to cook. We make soup together. Cooking is fun when we do it as a team.", "imageUrl": "https://example.com/cooking.jpg"}', 18, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('The Night Sky', '{"type": "article", "text": "At night, the sky is dark. I can see the moon and many stars. The stars look like tiny lights in the sky.", "imageUrl": "https://example.com/night-sky.jpg"}', 19, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('My Best Friend', '{"type": "article", "text": "My best friend lives next door. We play together every day. She has long hair and likes to draw pictures.", "imageUrl": "https://example.com/friends.jpg"}', 20, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
INSERT INTO content_items (title, content, "order", chapter_id) VALUES
('The Community Garden', '{"type": "article", "text": "Our neighborhood decided to create a community garden last spring. Everyone contributed by bringing seeds, tools, or their time. Now we have fresh vegetables and herbs that we share with each other. The garden has brought our community closer together.", "imageUrl": "https://example.com/community-garden.jpg"}', 1, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('Learning a New Language', '{"type": "article", "text": "Learning English as a second language can be challenging but rewarding. It opens doors to new opportunities and allows you to communicate with people from different cultures. Practice every day, even if it is just for fifteen minutes.", "imageUrl": "https://example.com/language-learning.jpg"}', 2, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('The Local Library', '{"type": "article", "text": "The public library is more than just a place to borrow books. It offers computer classes, reading groups, and homework help for students. Many people come here to study or attend cultural events throughout the year.", "imageUrl": "https://example.com/library.jpg"}', 3, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('Healthy Living Tips', '{"type": "article", "text": "Maintaining good health requires a balanced diet, regular exercise, and adequate sleep. Try to eat five servings of fruits and vegetables daily. Walk for at least thirty minutes and aim for eight hours of sleep each night.", "imageUrl": "https://example.com/healthy-living.jpg"}', 4, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('The Science Museum', '{"type": "article", "text": "Yesterday we visited the science museum with our class. We learned about dinosaurs, space exploration, and the human body. The interactive exhibits made learning fun and engaging for everyone.", "imageUrl": "https://example.com/science-museum.jpg"}', 5, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('Environmental Protection', '{"type": "article", "text": "Protecting our environment is everyone''s responsibility. Simple actions like recycling, using less water, and choosing public transportation can make a significant difference. Small changes in our daily habits can help preserve our planet.", "imageUrl": "https://example.com/environment.jpg"}', 6, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('Starting a Small Business', '{"type": "article", "text": "Many people dream of starting their own business. Success requires careful planning, hard work, and determination. Research your market, create a business plan, and be prepared to face challenges along the way.", "imageUrl": "https://example.com/business.jpg"}', 7, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('Cultural Traditions', '{"type": "article", "text": "Every culture has unique traditions that are passed down through generations. These customs help preserve history and bring families together. Celebrating cultural diversity enriches our understanding of the world.", "imageUrl": "https://example.com/traditions.jpg"}', 8, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('Technology in Education', '{"type": "article", "text": "Modern technology has transformed how students learn. Online courses, educational apps, and virtual reality experiences provide new ways to access information. However, traditional teaching methods still play an important role.", "imageUrl": "https://example.com/education-tech.jpg"}', 9, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('The Art of Cooking', '{"type": "article", "text": "Cooking is both an art and a science. Understanding ingredients, techniques, and flavors helps create delicious meals. Start with simple recipes and gradually experiment with more complex dishes as your skills improve.", "imageUrl": "https://example.com/cooking-art.jpg"}', 10, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('Travel Safety Tips', '{"type": "article", "text": "When traveling to new places, safety should always be your priority. Research your destination, keep copies of important documents, and stay aware of your surroundings. Trust your instincts and avoid risky situations.", "imageUrl": "https://example.com/travel-safety.jpg"}', 11, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('The Benefits of Reading', '{"type": "article", "text": "Reading regularly improves vocabulary, concentration, and critical thinking skills. It also reduces stress and provides entertainment. Whether you prefer fiction or non-fiction, developing a reading habit benefits your mind.", "imageUrl": "https://example.com/reading-benefits.jpg"}', 12, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('Managing Time Effectively', '{"type": "article", "text": "Good time management is essential for success in both personal and professional life. Create a schedule, set priorities, and avoid procrastination. Remember to include time for relaxation and activities you enjoy.", "imageUrl": "https://example.com/time-management.jpg"}', 13, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('The Importance of Exercise', '{"type": "article", "text": "Regular physical activity strengthens your heart, builds muscle, and improves mental health. Find activities you enjoy, whether it is dancing, swimming, or hiking. Exercise does not have to be boring or difficult.", "imageUrl": "https://example.com/exercise.jpg"}', 14, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('Social Media Impact', '{"type": "article", "text": "Social media has changed how we communicate and share information. While it connects people across distances, it also presents challenges like cyberbullying and privacy concerns. Use social media responsibly and mindfully.", "imageUrl": "https://example.com/social-media.jpg"}', 15, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('Career Planning', '{"type": "article", "text": "Planning your career path requires self-reflection and research. Consider your interests, skills, and values when exploring different professions. Networking and gaining relevant experience can help you achieve your goals.", "imageUrl": "https://example.com/career-planning.jpg"}', 16, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('Renewable Energy', '{"type": "article", "text": "Renewable energy sources like solar and wind power are becoming increasingly important. They provide clean alternatives to fossil fuels and help reduce greenhouse gas emissions. Investment in renewable technology continues to grow worldwide.", "imageUrl": "https://example.com/renewable-energy.jpg"}', 17, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('Volunteer Work', '{"type": "article", "text": "Volunteering allows you to give back to your community while developing new skills and meeting like-minded people. Many organizations need volunteers for various causes, from animal welfare to education support.", "imageUrl": "https://example.com/volunteer.jpg"}', 18, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('Financial Planning', '{"type": "article", "text": "Managing your finances wisely is crucial for achieving long-term goals. Create a budget, save regularly, and avoid unnecessary debt. Learning about investments and retirement planning early can secure your financial future.", "imageUrl": "https://example.com/financial-planning.jpg"}', 19, '361b770a-8792-4af4-82ce-8a69348dbf20'),
('Digital Literacy', '{"type": "article", "text": "In today''s digital world, computer skills are essential. Learn to use common software, understand internet safety, and stay updated with technology trends. Digital literacy opens opportunities in almost every field.", "imageUrl": "https://example.com/digital-literacy.jpg"}', 20, '361b770a-8792-4af4-82ce-8a69348dbf20');